1	////////////////////////////////////////////////////////////////////////////////
2	//
3	// Filename:	rtl/ex/wbpriarbiter.v
4	// {{{
5	// Project:	Zip CPU -- a small, lightweight, RISC CPU soft core
6	//
7	// Purpose:	This is a priority bus arbiter.  It allows two separate wishbone
8	//		masters to connect to the same bus, while also guaranteeing
9	//	that one master can have the bus with no delay any time the other
10	//	master is not using the bus.  The goal is to eliminate the combinatorial
11	//	logic required in the other wishbone arbiter, while still guarateeing
12	//	access time for the priority channel.
13	//
14	//	The core logic works like this:
15	//
16	//	1. When no one requests the bus, 'A' is granted the bus and guaranteed
17	//		that any access will go right through.
18	//	2. If 'B' requests the bus (asserts cyc), and the bus is idle, then
19	//		'B' will be granted the bus.
20	//	3. Bus grants last as long as the 'cyc' line is high.
21	//	4. Once 'cyc' is dropped, the bus returns to 'A' as the owner.
22	//
23	//
24	// Creator:	Dan Gisselquist, Ph.D.
25	//		Gisselquist Technology, LLC
26	//
27	////////////////////////////////////////////////////////////////////////////////
28	// }}}
29	// Copyright (C) 2015-2025, Gisselquist Technology, LLC
30	// {{{
31	// This program is free software (firmware): you can redistribute it and/or
32	// modify it under the terms of the GNU General Public License as published
33	// by the Free Software Foundation, either version 3 of the License, or (at
34	// your option) any later version.
35	//
36	// This program is distributed in the hope that it will be useful, but WITHOUT
37	// ANY WARRANTY; without even the implied warranty of MERCHANTIBILITY or
38	// FITNESS FOR A PARTICULAR PURPOSE.  See the GNU General Public License
39	// for more details.
40	//
41	// You should have received a copy of the GNU General Public License along
42	// with this program.  (It's in the $(ROOT)/doc directory.  Run make with no
43	// target there if the PDF file isn't present.)  If not, see
44	// <http://www.gnu.org/licenses/> for a copy.
45	// }}}
46	// License:	GPL, v3, as defined and found on www.gnu.org,
47	// {{{
48	//		http://www.gnu.org/licenses/gpl.html
49	//
50	////////////////////////////////////////////////////////////////////////////////
51	//
52	`default_nettype	none
53	// }}}
54	module	wbpriarbiter #(
55			// {{{
56			parameter			DW=32, AW=32,
57			// OPT_ZERO_ON_IDLE
58			// {{{
59			// ZERO_ON_IDLE uses more logic than the alternative.  It should
60			// be useful for reducing power, as these circuits tend to drive
61			// wires all the way across the design, but it may also slow
62			// down the master clock.  I've used it as an option when using
63			// VER1LATOR, 'cause zeroing things on idle can make them stand
64			// out all the more when staring at wires and dumps and such.
65			parameter	[0:0]		OPT_ZERO_ON_IDLE = 1'b0
66			// }}}
67			// }}}
68		) (
69			// {{{
70			input	wire			i_clk,
71			// Bus A
72			// {{{
73			input	wire			i_a_cyc, i_a_stb, i_a_we,
74			input	wire	[(AW-1):0]	i_a_adr,
75			input	wire	[(DW-1):0]	i_a_dat,
76			input	wire	[(DW/8-1):0]	i_a_sel,
77			output	wire			o_a_stall, o_a_ack, o_a_err,
78			// }}}
79			// Bus B
80			// {{{
81			input	wire			i_b_cyc, i_b_stb, i_b_we,
82			input	wire	[(AW-1):0]	i_b_adr,
83			input	wire	[(DW-1):0]	i_b_dat,
84			input	wire	[(DW/8-1):0]	i_b_sel,
85			output	wire			o_b_stall, o_b_ack, o_b_err,
86			// }}}
87			// Outgoing combined bus
88			// {{{
89			output	wire			o_cyc, o_stb, o_we,
90			output	wire	[(AW-1):0]	o_adr,
91			output	wire	[(DW-1):0]	o_dat,
92			output	wire	[(DW/8-1):0]	o_sel,
93			input	wire			i_stall, i_ack, i_err
94			// }}}
95			// }}}
96		);
97	
98		reg	r_a_owner;
99	
100		// r_a_owner
101		// {{{
102		// Go high immediately (new cycle) if ...
103		//	Previous cycle was low and *someone* is requesting a bus cycle
104		// Go low immadiately if ...
105		//	We were just high and the owner no longer wants the bus
106		// WISHBONE Spec recommends no logic between a FF and the o_cyc
107		//	This violates that spec.  (Rec 3.15, p35)
108		initial	r_a_owner = 1'b1;
109		always @(posedge i_clk)
110		if (!i_b_cyc)
111			r_a_owner <= 1'b1;
112		// Allow B to set its CYC line w/o activating this interface
113		else if ((i_b_cyc)&&(i_b_stb)&&(!i_a_cyc))
114			r_a_owner <= 1'b0;
115		// }}}
116	
117		// CYC, STB, and WE
118		// {{{
119		// Realistically, if neither master owns the bus, the output is a
120		// don't care.  Thus we trigger off whether or not 'A' owns the bus.
121		// If 'B' owns it all we care is that 'A' does not.  Likewise, if
122		// neither owns the bus than the values on these various lines are
123		// irrelevant.
124	
125		assign o_cyc = (r_a_owner) ? i_a_cyc : i_b_cyc;
126		assign o_we  = (r_a_owner) ? i_a_we  : i_b_we;
127		assign o_stb   = (r_a_owner) ? i_a_stb   : i_b_stb;
128		// }}}
129	
130		// Everything else
131		// {{{
132		generate if (OPT_ZERO_ON_IDLE)
133		begin : OPT_LOWPOWER
134			// {{{
135			assign	o_adr     = (o_stb)?((r_a_owner) ? i_a_adr  : i_b_adr):0;
136			assign	o_dat     = (o_stb)?((r_a_owner) ? i_a_dat  : i_b_dat):0;
137			assign	o_sel     = (o_stb)?((r_a_owner) ? i_a_sel  : i_b_sel):0;
138			assign	o_a_ack   = (o_cyc)&&( r_a_owner) ? i_ack   : 1'b0;
139			assign	o_b_ack   = (o_cyc)&&(!r_a_owner) ? i_ack   : 1'b0;
140			assign	o_a_stall = (o_cyc)&&( r_a_owner) ? i_stall : 1'b1;
141			assign	o_b_stall = (o_cyc)&&(!r_a_owner) ? i_stall : 1'b1;
142			assign	o_a_err   = (o_cyc)&&( r_a_owner) ? i_err : 1'b0;
143			assign	o_b_err   = (o_cyc)&&(!r_a_owner) ? i_err : 1'b0;
144			// }}}
145		end else begin : OPT_LOWLOGIC
146			// {{{
147			assign o_adr   = (r_a_owner) ? i_a_adr   : i_b_adr;
148			assign o_dat   = (r_a_owner) ? i_a_dat   : i_b_dat;
149			assign o_sel   = (r_a_owner) ? i_a_sel   : i_b_sel;
150	
151			// We cannot allow the return acknowledgement to ever go high if
152			// the master in question does not own the bus.  Hence we force it
153			// low if the particular master doesn't own the bus.
154			assign	o_a_ack   = ( r_a_owner) ? i_ack   : 1'b0;
155			assign	o_b_ack   = (!r_a_owner) ? i_ack   : 1'b0;
156	
157			// Stall must be asserted on the same cycle the input master asserts
158			// the bus, if the bus isn't granted to him.
159			assign	o_a_stall = ( r_a_owner) ? i_stall : 1'b1;
160			assign	o_b_stall = (!r_a_owner) ? i_stall : 1'b1;
161	
162			//
163			//
164			assign	o_a_err = ( r_a_owner) ? i_err : 1'b0;
165			assign	o_b_err = (!r_a_owner) ? i_err : 1'b0;
166			// }}}
167		end endgenerate
168		// }}}
169	////////////////////////////////////////////////////////////////////////////////
170	////////////////////////////////////////////////////////////////////////////////
171	////////////////////////////////////////////////////////////////////////////////
172	//
173	// Formal properties
174	// {{{
175	////////////////////////////////////////////////////////////////////////////////
176	////////////////////////////////////////////////////////////////////////////////
177	////////////////////////////////////////////////////////////////////////////////
178	`ifdef	FORMAL
179	`ifdef	WBPRIARBITER
180	`define	ASSUME	assume
181	`else
182	`define	ASSUME	assert
183	`endif
184	
185		reg	f_past_valid;
186		initial	f_past_valid = 1'b0;
187		always @(posedge i_clk)
188			f_past_valid <= 1'b1;
189	
190		initial	assume(!i_a_cyc);
191		initial	assume(!i_a_stb);
192	
193		initial	assume(!i_b_cyc);
194		initial	assume(!i_b_stb);
195	
196		initial	assume(!i_ack);
197		initial	assume(!i_err);
198	
199		always @(posedge i_clk)
200		begin
201			if (o_cyc)
202				assert((i_a_cyc)||(i_b_cyc));
203			if ((f_past_valid)&&($past(o_cyc))&&(o_cyc))
204				assert($past(r_a_owner) == r_a_owner);
205			if ((f_past_valid)&&($past(!o_cyc))&&($past(i_a_stb)))
206				assert(r_a_owner);
207			if ((f_past_valid)&&($past(!o_cyc))&&($past(i_b_stb)))
208				assert(!r_a_owner);
209		end
210	
211		reg	f_reset;
212		initial	f_reset = 1'b1;
213		always @(posedge i_clk)
214			f_reset <= 1'b0;
215		always @(*)
216			if (!f_past_valid)
217				assert(f_reset);
218	
219		parameter	F_LGDEPTH=3;
220	
221		wire	[(F_LGDEPTH-1):0]	f_nreqs, f_nacks, f_outstanding,
222				f_a_nreqs, f_a_nacks, f_a_outstanding,
223				f_b_nreqs, f_b_nacks, f_b_outstanding;
224	
225		fwb_master #(
226			// {{{
227			.F_MAX_STALL(0),
228				.F_LGDEPTH(F_LGDEPTH),
229				.F_MAX_ACK_DELAY(0),
230				.F_OPT_RMW_BUS_OPTION(1),
231				.F_OPT_DISCONTINUOUS(1)
232			// }}}
233		) f_wbm(
234			// {{{
235			i_clk, f_reset,
236				o_cyc, o_stb, o_we, o_adr, o_dat, o_sel,
237				i_ack, i_stall, 32'h0, i_err,
238				f_nreqs, f_nacks, f_outstanding
239			// }}}
240		);
241	
242		fwb_slave  #(
243			// {{{
244			.F_MAX_STALL(0),
245				.F_LGDEPTH(F_LGDEPTH),
246				.F_MAX_ACK_DELAY(0),
247				.F_OPT_RMW_BUS_OPTION(1),
248				.F_OPT_DISCONTINUOUS(1)
249			// }}}
250		) f_wba(
251			// {{{
252			i_clk, f_reset,
253				i_a_cyc, i_a_stb, i_a_we, i_a_adr, i_a_dat, i_a_sel,
254				o_a_ack, o_a_stall, 32'h0, o_a_err,
255				f_a_nreqs, f_a_nacks, f_a_outstanding
256			// }}}
257		);
258	
259		fwb_slave  #(
260			// {{{
261			.F_MAX_STALL(0),
262				.F_LGDEPTH(F_LGDEPTH),
263				.F_MAX_ACK_DELAY(0),
264				.F_OPT_RMW_BUS_OPTION(1),
265				.F_OPT_DISCONTINUOUS(1)
266			// }}}
267		) f_wbb(
268			// {{{
269			i_clk, f_reset,
270			i_b_cyc, i_b_stb, i_b_we, i_b_adr, i_b_dat, i_b_sel,
271			o_b_ack, o_b_stall, 32'h0, o_b_err,
272			f_b_nreqs, f_b_nacks, f_b_outstanding
273			// }}}
274		);
275	
276		// Induction, relate number of requests and acks to r_a_owner
277		// {{{
278		always @(posedge i_clk)
279		if (r_a_owner)
280		begin
281			assert(f_b_nreqs == 0);
282			assert(f_b_nacks == 0);
283			assert(f_a_outstanding == f_outstanding);
284		end else begin
285			assert(f_a_nreqs == 0);
286			assert(f_a_nacks == 0);
287			assert(f_b_outstanding == f_outstanding);
288		end
289		// }}}
290	
291		always @(posedge i_clk)
292		if ((r_a_owner)&&(i_b_cyc))
293				assume(i_b_stb);
294	
295		always @(posedge i_clk)
296		if ((r_a_owner)&&(i_a_cyc))
297			assume(i_a_stb);
298	`endif
299	// }}}
300	endmodule
