1	////////////////////////////////////////////////////////////////////////////////
2	//
3	// Filename: 	sfifo.v
4	// {{{
5	// Project:	Zip CPU -- a small, lightweight, RISC CPU soft core
6	//
7	// Purpose:	A synchronous data FIFO.
8	//
9	// Creator:	Dan Gisselquist, Ph.D.
10	//		Gisselquist Technology, LLC
11	//
12	////////////////////////////////////////////////////////////////////////////////
13	//
14	// Written and distributed by Gisselquist Technology, LLC
15	// }}}
16	// This design is hereby granted to the public domain.
17	// {{{
18	// This program is distributed in the hope that it will be useful, but WITHOUT
19	// ANY WARRANTY; without even the implied warranty of MERCHANTIBILITY or
20	// FITNESS FOR A PARTICULAR PURPOSE.
21	//
22	////////////////////////////////////////////////////////////////////////////////
23	//
24	`default_nettype	none
25	// }}}
26	module sfifo #(
27			// {{{
28			parameter	BW=8,	// Byte/data width
29			parameter 	LGFLEN=4,
30			parameter [0:0]	OPT_ASYNC_READ = 1'b1,
31			parameter [0:0]	OPT_WRITE_ON_FULL = 1'b0,
32			parameter [0:0]	OPT_READ_ON_EMPTY = 1'b0
33			// }}}
34		) (
35			// {{{
36			input	wire		i_clk,
37			input	wire		i_reset,
38			//
39			// Write interface
40			input	wire		i_wr,
41			input	wire [(BW-1):0]	i_data,
42			output	wire 		o_full,
43			output	reg [LGFLEN:0]	o_fill,
44			//
45			// Read interface
46			input	wire		i_rd,
47			output	reg [(BW-1):0]	o_data,
48			output	wire		o_empty	// True if FIFO is empty
49	`ifdef	FORMAL
50	`ifdef	F_PEEK
51			, output wire	[LGFLEN:0]	f_first_addr,
52			output	wire	[LGFLEN:0]	f_second_addr,
53			output	reg	[BW-1:0]	f_first_data, f_second_data,
54	
55			output	reg			f_first_in_fifo,
56							f_second_in_fifo,
57			output	reg	[LGFLEN:0]	f_distance_to_first,
58							f_distance_to_second
59	`endif
60	`endif
61			// }}}
62		);
63	
64		// Register/net declarations
65		// {{{
66		localparam	FLEN=(1<<LGFLEN);
67		reg			r_full, r_empty;
68		reg	[(BW-1):0]	mem[0:(FLEN-1)];
69		reg	[LGFLEN:0]	wr_addr, rd_addr;
70	
71		wire	w_wr = (i_wr && !o_full);
72		wire	w_rd = (i_rd && !o_empty);
73		// }}}
74		////////////////////////////////////////////////////////////////////////
75		//
76		// Write half
77		// {{{
78		////////////////////////////////////////////////////////////////////////
79		//
80		//
81	
82		// o_fill
83		// {{{
84		initial	o_fill = 0;
85		always @(posedge i_clk)
86		if (i_reset)
87			o_fill <= 0;
88		else case({ w_wr, w_rd })
89		2'b01: o_fill <= o_fill - 1;
90		2'b10: o_fill <= o_fill + 1;
91		default: o_fill <= wr_addr - rd_addr;
92		endcase
93		// }}}
94	
95		// r_full, o_full
96		// {{{
97		initial	r_full = 0;
98		always @(posedge i_clk)
99		if (i_reset)
100			r_full <= 0;
101		else case({ w_wr, w_rd})
102		2'b01: r_full <= 1'b0;
103		2'b10: r_full <= (o_fill == { 1'b0, {(LGFLEN){1'b1}} });
104		default: r_full <= (o_fill == { 1'b1, {(LGFLEN){1'b0}} });
105		endcase
106	
107		assign	o_full = (i_rd && OPT_WRITE_ON_FULL) ? 1'b0 : r_full;
108		// }}}
109	
110		// wr_addr, the write address pointer
111		// {{{
112		initial	wr_addr = 0;
113		always @(posedge i_clk)
114		if (i_reset)
115			wr_addr <= 0;
116		else if (w_wr)
117			wr_addr <= wr_addr + 1'b1;
118		// }}}
119	
120		// Write to memory
121		// {{{
122		always @(posedge i_clk)
123		if (w_wr)
124			mem[wr_addr[(LGFLEN-1):0]] <= i_data;
125		// }}}
126		// }}}
127		////////////////////////////////////////////////////////////////////////
128		//
129		// Read half
130		// {{{
131		////////////////////////////////////////////////////////////////////////
132		//
133		//
134	
135		// rd_addr, the read address pointer
136		// {{{
137		initial	rd_addr = 0;
138		always @(posedge i_clk)
139		if (i_reset)
140			rd_addr <= 0;
141		else if (w_rd)
142			rd_addr <= rd_addr + 1;
143		// }}}
144	
145		// r_empty, o_empty
146		// {{{
147		initial	r_empty = 1'b1;
148		always @(posedge i_clk)
149		if (i_reset)
150			r_empty <= 1'b1;
151		else case ({ w_wr, w_rd })
152		2'b01: r_empty <= (o_fill <= 1);
153		2'b10: r_empty <= 1'b0;
154		default: begin end
155		endcase
156	
157		assign	o_empty = (OPT_READ_ON_EMPTY && i_wr) ? 1'b0 : r_empty;
158		// }}}
159	
160		// Read from the FIFO
161		// {{{
162		generate if (OPT_ASYNC_READ && OPT_READ_ON_EMPTY)
163		begin : ASYNCHRONOUS_READ_ON_EMPTY
164			// o_data
165			// {{{
166			always @(*)
167			begin
168				o_data = mem[rd_addr[LGFLEN-1:0]];
169				if (r_empty)
170					o_data = i_data;
171			end
172			// }}}
173		end else if (OPT_ASYNC_READ)
174		begin : ASYNCHRONOUS_READ
175			// o_data
176			// {{{
177			always @(*)
178				o_data = mem[rd_addr[LGFLEN-1:0]];
179			// }}}
180		end else begin : REGISTERED_READ
181			// {{{
182			reg		bypass_valid;
183			reg [BW-1:0]	bypass_data, rd_data;
184			reg [LGFLEN-1:0]	rd_next;
185	
186			always @(*)
187				rd_next = rd_addr[LGFLEN-1:0] + 1;
188	
189			// Memory read, bypassing it if we must
190			// {{{
191			initial bypass_valid = 0;
192			always @(posedge i_clk)
193			if (i_reset)
194				bypass_valid <= 0;
195			else if (r_empty || i_rd)
196			begin
197				if (!i_wr)
198					bypass_valid <= 1'b0;
199				else if (r_empty || (i_rd && (o_fill == 1)))
200					bypass_valid <= 1'b1;
201				else
202					bypass_valid <= 1'b0;
203			end
204	
205			always @(posedge i_clk)
206			if (r_empty || i_rd)
207				bypass_data <= i_data;
208	
209			initial mem[0] = 0;
210			initial rd_data = 0;
211			always @(posedge i_clk)
212			if (w_rd)
213				rd_data <= mem[rd_next];
214	
215			always @(*)
216			if (OPT_READ_ON_EMPTY && r_empty)
217				o_data = i_data;
218			else if (bypass_valid)
219				o_data = bypass_data;
220			else
221				o_data = rd_data;
222			// }}}
223			// }}}
224		end endgenerate
225		// }}}
226		// }}}
227	////////////////////////////////////////////////////////////////////////////////
228	////////////////////////////////////////////////////////////////////////////////
229	////////////////////////////////////////////////////////////////////////////////
230	//
231	// FORMAL METHODS
232	// {{{
233	////////////////////////////////////////////////////////////////////////////////
234	////////////////////////////////////////////////////////////////////////////////
235	////////////////////////////////////////////////////////////////////////////////
236	`ifdef	FORMAL
237	
238	//
239	// Assumptions about our input(s)
240	//
241	//
242	`ifdef	SFIFO
243	`define	ASSUME	assume
244	`else
245	`define	ASSUME	assert
246	`endif
247	
248		reg			f_past_valid;
249		wire	[LGFLEN:0]	f_fill, f_next;
250		wire			f_empty;
251	
252		initial	f_past_valid = 1'b0;
253		always @(posedge i_clk)
254			f_past_valid <= 1'b1;
255	
256		////////////////////////////////////////////////////////////////////////
257		//
258		// Assertions about our flags and counters
259		// {{{
260		////////////////////////////////////////////////////////////////////////
261		//
262		//
263	
264		assign	f_fill = wr_addr - rd_addr;
265		assign	f_empty = (wr_addr == rd_addr);
266		assign	f_next = rd_addr + 1'b1;
267	
268		always @(*)
269		begin
270			assert(f_fill <= { 1'b1, {(LGFLEN){1'b0}} });
271			assert(o_fill == f_fill);
272	
273			assert(r_full  == (f_fill == {1'b1, {(LGFLEN){1'b0}} }));
274			assert(r_empty == (f_fill == 0));
275	
276			if (!OPT_WRITE_ON_FULL)
277			begin
278				assert(o_full == r_full);
279			end else begin
280				assert(o_full == (r_full && !i_rd));
281			end
282	
283			if (!OPT_READ_ON_EMPTY)
284			begin
285				assert(o_empty == r_empty);
286			end else begin
287				assert(o_empty == (r_empty && !i_wr));
288			end
289		end
290	
291		always @(posedge i_clk)
292		if (!OPT_ASYNC_READ && f_past_valid)
293		begin
294			if (f_fill == 0)
295			begin
296				assert(r_empty);
297				assert(o_empty || (OPT_READ_ON_EMPTY && i_wr));
298			end else if ($past(f_fill)>1)
299			begin
300				assert(!r_empty);
301			end else if ($past(!i_rd && f_fill > 0))
302				assert(!r_empty);
303		end
304	
305		always @(*)
306		if (!r_empty)
307		begin
308			// This also applies for the registered read case
309			assert(mem[rd_addr[LGFLEN-1:0]] == o_data);
310		end else if (OPT_READ_ON_EMPTY)
311			assert(o_data == i_data);
312	
313		// }}}
314		////////////////////////////////////////////////////////////////////////
315		//
316		// Formal contract: (Twin write test)
317		// {{{
318		// If you write two values in succession, you should be able to read
319		// those same two values in succession some time later.
320		//
321		////////////////////////////////////////////////////////////////////////
322		//
323		//
324	
325		// Verilator lint_off UNDRIVEN
326		(* anyconst *)	reg	[LGFLEN:0]	fw_first_addr;
327		// Verilator lint_on  UNDRIVEN
328	`ifndef	F_PEEK
329				wire	[LGFLEN:0]	f_first_addr;
330				wire	[LGFLEN:0]	f_second_addr;
331				reg	[BW-1:0]	f_first_data, f_second_data;
332	
333		reg	f_first_in_fifo, f_second_in_fifo;
334		reg	[LGFLEN:0]	f_distance_to_first, f_distance_to_second;
335	`endif
336		reg	f_first_addr_in_fifo, f_second_addr_in_fifo;
337	
338		assign f_first_addr  = fw_first_addr;
339		assign f_second_addr = f_first_addr + 1;
340	
341		always @(*)
342		begin
343			f_distance_to_first = (f_first_addr - rd_addr);
344			f_first_addr_in_fifo = 0;
345			if ((f_fill != 0) && (f_distance_to_first < f_fill))
346				f_first_addr_in_fifo = 1;
347		end
348	
349		always @(*)
350		begin
351			f_distance_to_second = (f_second_addr - rd_addr);
352			f_second_addr_in_fifo = 0;
353			if ((f_fill != 0) && (f_distance_to_second < f_fill))
354				f_second_addr_in_fifo = 1;
355		end
356	
357		always @(posedge i_clk)
358		if (w_wr && wr_addr == f_first_addr)
359			f_first_data <= i_data;
360	
361		always @(posedge i_clk)
362		if (w_wr && wr_addr == f_second_addr)
363			f_second_data <= i_data;
364	
365		always @(*)
366		if (f_first_addr_in_fifo)
367			assert(mem[f_first_addr[LGFLEN-1:0]] == f_first_data);
368		always @(*)
369			f_first_in_fifo = (f_first_addr_in_fifo && (mem[f_first_addr[LGFLEN-1:0]] == f_first_data));
370	
371		always @(*)
372		if (f_second_addr_in_fifo)
373			assert(mem[f_second_addr[LGFLEN-1:0]] == f_second_data);
374	
375		always @(*)
376			f_second_in_fifo = (f_second_addr_in_fifo && (mem[f_second_addr[LGFLEN-1:0]] == f_second_data));
377	
378		always @(*)
379		if (f_first_in_fifo && (o_fill == 1 || f_distance_to_first == 0))
380			assert(o_data == f_first_data);
381	
382		always @(*)
383		if (f_second_in_fifo && (o_fill == 1 || f_distance_to_second == 0))
384			assert(o_data == f_second_data);
385	
386		always @(posedge i_clk)
387		if (f_past_valid && !$past(i_reset))
388		begin
389			case({$past(f_first_in_fifo), $past(f_second_in_fifo)})
390			2'b00: begin
391					if ($past(w_wr && (!w_rd || !r_empty))
392						&&($past(wr_addr == f_first_addr)))
393					begin
394						assert(f_first_in_fifo);
395					end else begin
396						assert(!f_first_in_fifo);
397					end
398					//
399					// The second could be in the FIFO, since
400					// one might write other data than f_first_data
401					//
402					// assert(!f_second_in_fifo);
403				end
404			2'b01: begin
405					assert(!f_first_in_fifo);
406					if ($past(w_rd && (rd_addr==f_second_addr)))
407					begin
408						assert((o_empty&&!OPT_ASYNC_READ)||!f_second_in_fifo);
409					end else begin
410						assert(f_second_in_fifo);
411					end
412				end
413			2'b10: begin
414					if ($past(w_wr)
415						&&($past(wr_addr == f_second_addr)))
416					begin
417						assert(f_second_in_fifo);
418					end else begin
419						assert(!f_second_in_fifo);
420					end
421					if ($past(!w_rd ||(rd_addr != f_first_addr)))
422						assert(f_first_in_fifo);
423				end
424			2'b11: begin
425					assert(f_second_in_fifo);
426					if ($past(!w_rd ||(rd_addr != f_first_addr)))
427					begin
428						assert(f_first_in_fifo);
429						if (rd_addr == f_first_addr)
430							assert(o_data == f_first_data);
431					end else begin
432						assert(!f_first_in_fifo);
433						assert(o_data == f_second_data);
434					end
435				end
436			endcase
437		end
438		// }}}
439		////////////////////////////////////////////////////////////////////////
440		//
441		//	Cover properties
442		// {{{
443		////////////////////////////////////////////////////////////////////////
444		//
445		//
446	`ifdef	SFIFO
447		reg	f_was_full;
448		initial	f_was_full = 0;
449		always @(posedge i_clk)
450		if (o_full)
451			f_was_full <= 1;
452	
453		always @(posedge i_clk)
454			cover($fell(f_empty));
455	
456		always @(posedge i_clk)
457			cover($fell(o_empty));
458	
459		always @(posedge i_clk)
460			cover(f_was_full && f_empty);
461	
462		always @(posedge i_clk)
463			cover($past(o_full,2)&&(!$past(o_full))&&(o_full));
464	
465		always @(posedge i_clk)
466		if (f_past_valid)
467			cover($past(o_empty,2)&&(!$past(o_empty))&& o_empty);
468	`endif
469		// }}}
470	
471		// Make Verilator happy
472		// Verilator lint_off UNUSED
473		wire	unused_formal;
474		assign	unused_formal = &{ 1'b0, f_next[LGFLEN], f_empty };
475		// Verilator lint_on  UNUSED
476	`endif // FORMAL
477	// }}}
478	endmodule
479

file.content:
////////////////////////////////////////////////////////////////////////////////
//
// Filename: 	sfifo.v
// {{{
// Project:	Zip CPU -- a small, lightweight, RISC CPU soft core
//
// Purpose:	A synchronous data FIFO.
//
// Creator:	Dan Gisselquist, Ph.D.
//		Gisselquist Technology, LLC
//
////////////////////////////////////////////////////////////////////////////////
//
// Written and distributed by Gisselquist Technology, LLC
// }}}
// This design is hereby granted to the public domain.
// {{{
// This program is distributed in the hope that it will be useful, but WITHOUT
// ANY WARRANTY; without even the implied warranty of MERCHANTIBILITY or
// FITNESS FOR A PARTICULAR PURPOSE.
//
////////////////////////////////////////////////////////////////////////////////
//
`default_nettype	none
// }}}
module sfifo #(
		// {{{
		parameter	BW=8,	// Byte/data width
		parameter 	LGFLEN=4,
		parameter [0:0]	OPT_ASYNC_READ = 1'b1,
		parameter [0:0]	OPT_WRITE_ON_FULL = 1'b0,
		parameter [0:0]	OPT_READ_ON_EMPTY = 1'b0
		// }}}
	) (
		// {{{
		input	wire		i_clk,
		input	wire		i_reset,
		//
		// Write interface
		input	wire		i_wr,
		input	wire [(BW-1):0]	i_data,
		output	wire 		o_full,
		output	reg [LGFLEN:0]	o_fill,
		//
		// Read interface
		input	wire		i_rd,
		output	reg [(BW-1):0]	o_data,
		output	wire		o_empty	// True if FIFO is empty
`ifdef	FORMAL
`ifdef	F_PEEK
		, output wire	[LGFLEN:0]	f_first_addr,
		output	wire	[LGFLEN:0]	f_second_addr,
		output	reg	[BW-1:0]	f_first_data, f_second_data,

		output	reg			f_first_in_fifo,
						f_second_in_fifo,
		output	reg	[LGFLEN:0]	f_distance_to_first,
						f_distance_to_second
`endif
`endif
		// }}}
	);

	// Register/net declarations
	// {{{
	localparam	FLEN=(1<<LGFLEN);
	reg			r_full, r_empty;
	reg	[(BW-1):0]	mem[0:(FLEN-1)];
	reg	[LGFLEN:0]	wr_addr, rd_addr;

	wire	w_wr = (i_wr && !o_full);
	wire	w_rd = (i_rd && !o_empty);
	// }}}
	////////////////////////////////////////////////////////////////////////
	//
	// Write half
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//

	// o_fill
	// {{{
	initial	o_fill = 0;
	always @(posedge i_clk)
	if (i_reset)
		o_fill <= 0;
	else case({ w_wr, w_rd })
	2'b01: o_fill <= o_fill - 1;
	2'b10: o_fill <= o_fill + 1;
	default: o_fill <= wr_addr - rd_addr;
	endcase
	// }}}

	// r_full, o_full
	// {{{
	initial	r_full = 0;
	always @(posedge i_clk)
	if (i_reset)
		r_full <= 0;
	else case({ w_wr, w_rd})
	2'b01: r_full <= 1'b0;
	2'b10: r_full <= (o_fill == { 1'b0, {(LGFLEN){1'b1}} });
	default: r_full <= (o_fill == { 1'b1, {(LGFLEN){1'b0}} });
	endcase

	assign	o_full = (i_rd && OPT_WRITE_ON_FULL) ? 1'b0 : r_full;
	// }}}

	// wr_addr, the write address pointer
	// {{{
	initial	wr_addr = 0;
	always @(posedge i_clk)
	if (i_reset)
		wr_addr <= 0;
	else if (w_wr)
		wr_addr <= wr_addr + 1'b1;
	// }}}

	// Write to memory
	// {{{
	always @(posedge i_clk)
	if (w_wr)
		mem[wr_addr[(LGFLEN-1):0]] <= i_data;
	// }}}
	// }}}
	////////////////////////////////////////////////////////////////////////
	//
	// Read half
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//

	// rd_addr, the read address pointer
	// {{{
	initial	rd_addr = 0;
	always @(posedge i_clk)
	if (i_reset)
		rd_addr <= 0;
	else if (w_rd)
		rd_addr <= rd_addr + 1;
	// }}}

	// r_empty, o_empty
	// {{{
	initial	r_empty = 1'b1;
	always @(posedge i_clk)
	if (i_reset)
		r_empty <= 1'b1;
	else case ({ w_wr, w_rd })
	2'b01: r_empty <= (o_fill <= 1);
	2'b10: r_empty <= 1'b0;
	default: begin end
	endcase

	assign	o_empty = (OPT_READ_ON_EMPTY && i_wr) ? 1'b0 : r_empty;
	// }}}

	// Read from the FIFO
	// {{{
	generate if (OPT_ASYNC_READ && OPT_READ_ON_EMPTY)
	begin : ASYNCHRONOUS_READ_ON_EMPTY
		// o_data
		// {{{
		always @(*)
		begin
			o_data = mem[rd_addr[LGFLEN-1:0]];
			if (r_empty)
				o_data = i_data;
		end
		// }}}
	end else if (OPT_ASYNC_READ)
	begin : ASYNCHRONOUS_READ
		// o_data
		// {{{
		always @(*)
			o_data = mem[rd_addr[LGFLEN-1:0]];
		// }}}
	end else begin : REGISTERED_READ
		// {{{
		reg		bypass_valid;
		reg [BW-1:0]	bypass_data, rd_data;
		reg [LGFLEN-1:0]	rd_next;

		always @(*)
			rd_next = rd_addr[LGFLEN-1:0] + 1;

		// Memory read, bypassing it if we must
		// {{{
		initial bypass_valid = 0;
		always @(posedge i_clk)
		if (i_reset)
			bypass_valid <= 0;
		else if (r_empty || i_rd)
		begin
			if (!i_wr)
				bypass_valid <= 1'b0;
			else if (r_empty || (i_rd && (o_fill == 1)))
				bypass_valid <= 1'b1;
			else
				bypass_valid <= 1'b0;
		end

		always @(posedge i_clk)
		if (r_empty || i_rd)
			bypass_data <= i_data;

		initial mem[0] = 0;
		initial rd_data = 0;
		always @(posedge i_clk)
		if (w_rd)
			rd_data <= mem[rd_next];

		always @(*)
		if (OPT_READ_ON_EMPTY && r_empty)
			o_data = i_data;
		else if (bypass_valid)
			o_data = bypass_data;
		else
			o_data = rd_data;
		// }}}
		// }}}
	end endgenerate
	// }}}
	// }}}
////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////
//
// FORMAL METHODS
// {{{
////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////
`ifdef	FORMAL

//
// Assumptions about our input(s)
//
//
`ifdef	SFIFO
`define	ASSUME	assume
`else
`define	ASSUME	assert
`endif

	reg			f_past_valid;
	wire	[LGFLEN:0]	f_fill, f_next;
	wire			f_empty;

	initial	f_past_valid = 1'b0;
	always @(posedge i_clk)
		f_past_valid <= 1'b1;

	////////////////////////////////////////////////////////////////////////
	//
	// Assertions about our flags and counters
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//

	assign	f_fill = wr_addr - rd_addr;
	assign	f_empty = (wr_addr == rd_addr);
	assign	f_next = rd_addr + 1'b1;

	always @(*)
	begin
		assert(f_fill <= { 1'b1, {(LGFLEN){1'b0}} });
		assert(o_fill == f_fill);

		assert(r_full  == (f_fill == {1'b1, {(LGFLEN){1'b0}} }));
		assert(r_empty == (f_fill == 0));

		if (!OPT_WRITE_ON_FULL)
		begin
			assert(o_full == r_full);
		end else begin
			assert(o_full == (r_full && !i_rd));
		end

		if (!OPT_READ_ON_EMPTY)
		begin
			assert(o_empty == r_empty);
		end else begin
			assert(o_empty == (r_empty && !i_wr));
		end
	end

	always @(posedge i_clk)
	if (!OPT_ASYNC_READ && f_past_valid)
	begin
		if (f_fill == 0)
		begin
			assert(r_empty);
			assert(o_empty || (OPT_READ_ON_EMPTY && i_wr));
		end else if ($past(f_fill)>1)
		begin
			assert(!r_empty);
		end else if ($past(!i_rd && f_fill > 0))
			assert(!r_empty);
	end

	always @(*)
	if (!r_empty)
	begin
		// This also applies for the registered read case
		assert(mem[rd_addr[LGFLEN-1:0]] == o_data);
	end else if (OPT_READ_ON_EMPTY)
		assert(o_data == i_data);

	// }}}
	////////////////////////////////////////////////////////////////////////
	//
	// Formal contract: (Twin write test)
	// {{{
	// If you write two values in succession, you should be able to read
	// those same two values in succession some time later.
	//
	////////////////////////////////////////////////////////////////////////
	//
	//

	// Verilator lint_off UNDRIVEN
	(* anyconst *)	reg	[LGFLEN:0]	fw_first_addr;
	// Verilator lint_on  UNDRIVEN
`ifndef	F_PEEK
			wire	[LGFLEN:0]	f_first_addr;
			wire	[LGFLEN:0]	f_second_addr;
			reg	[BW-1:0]	f_first_data, f_second_data;

	reg	f_first_in_fifo, f_second_in_fifo;
	reg	[LGFLEN:0]	f_distance_to_first, f_distance_to_second;
`endif
	reg	f_first_addr_in_fifo, f_second_addr_in_fifo;

	assign f_first_addr  = fw_first_addr;
	assign f_second_addr = f_first_addr + 1;

	always @(*)
	begin
		f_distance_to_first = (f_first_addr - rd_addr);
		f_first_addr_in_fifo = 0;
		if ((f_fill != 0) && (f_distance_to_first < f_fill))
			f_first_addr_in_fifo = 1;
	end

	always @(*)
	begin
		f_distance_to_second = (f_second_addr - rd_addr);
		f_second_addr_in_fifo = 0;
		if ((f_fill != 0) && (f_distance_to_second < f_fill))
			f_second_addr_in_fifo = 1;
	end

	always @(posedge i_clk)
	if (w_wr && wr_addr == f_first_addr)
		f_first_data <= i_data;

	always @(posedge i_clk)
	if (w_wr && wr_addr == f_second_addr)
		f_second_data <= i_data;

	always @(*)
	if (f_first_addr_in_fifo)
		assert(mem[f_first_addr[LGFLEN-1:0]] == f_first_data);
	always @(*)
		f_first_in_fifo = (f_first_addr_in_fifo && (mem[f_first_addr[LGFLEN-1:0]] == f_first_data));

	always @(*)
	if (f_second_addr_in_fifo)
		assert(mem[f_second_addr[LGFLEN-1:0]] == f_second_data);

	always @(*)
		f_second_in_fifo = (f_second_addr_in_fifo && (mem[f_second_addr[LGFLEN-1:0]] == f_second_data));

	always @(*)
	if (f_first_in_fifo && (o_fill == 1 || f_distance_to_first == 0))
		assert(o_data == f_first_data);

	always @(*)
	if (f_second_in_fifo && (o_fill == 1 || f_distance_to_second == 0))
		assert(o_data == f_second_data);

	always @(posedge i_clk)
	if (f_past_valid && !$past(i_reset))
	begin
		case({$past(f_first_in_fifo), $past(f_second_in_fifo)})
		2'b00: begin
				if ($past(w_wr && (!w_rd || !r_empty))
					&&($past(wr_addr == f_first_addr)))
				begin
					assert(f_first_in_fifo);
				end else begin
					assert(!f_first_in_fifo);
				end
				//
				// The second could be in the FIFO, since
				// one might write other data than f_first_data
				//
				// assert(!f_second_in_fifo);
			end
		2'b01: begin
				assert(!f_first_in_fifo);
				if ($past(w_rd && (rd_addr==f_second_addr)))
				begin
					assert((o_empty&&!OPT_ASYNC_READ)||!f_second_in_fifo);
				end else begin
					assert(f_second_in_fifo);
				end
			end
		2'b10: begin
				if ($past(w_wr)
					&&($past(wr_addr == f_second_addr)))
				begin
					assert(f_second_in_fifo);
				end else begin
					assert(!f_second_in_fifo);
				end
				if ($past(!w_rd ||(rd_addr != f_first_addr)))
					assert(f_first_in_fifo);
			end
		2'b11: begin
				assert(f_second_in_fifo);
				if ($past(!w_rd ||(rd_addr != f_first_addr)))
				begin
					assert(f_first_in_fifo);
					if (rd_addr == f_first_addr)
						assert(o_data == f_first_data);
				end else begin
					assert(!f_first_in_fifo);
					assert(o_data == f_second_data);
				end
			end
		endcase
	end
	// }}}
	////////////////////////////////////////////////////////////////////////
	//
	//	Cover properties
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//
`ifdef	SFIFO
	reg	f_was_full;
	initial	f_was_full = 0;
	always @(posedge i_clk)
	if (o_full)
		f_was_full <= 1;

	always @(posedge i_clk)
		cover($fell(f_empty));

	always @(posedge i_clk)
		cover($fell(o_empty));

	always @(posedge i_clk)
		cover(f_was_full && f_empty);

	always @(posedge i_clk)
		cover($past(o_full,2)&&(!$past(o_full))&&(o_full));

	always @(posedge i_clk)
	if (f_past_valid)
		cover($past(o_empty,2)&&(!$past(o_empty))&& o_empty);
`endif
	// }}}

	// Make Verilator happy
	// Verilator lint_off UNUSED
	wire	unused_formal;
	assign	unused_formal = &{ 1'b0, f_next[LGFLEN], f_empty };
	// Verilator lint_on  UNUSED
`endif // FORMAL
// }}}
endmodule

