1	////////////////////////////////////////////////////////////////////////////////
2	//
3	// Filename:	rtl/ex/skidbuffer.v
4	// {{{
5	// Project:	Zip CPU -- a small, lightweight, RISC CPU soft core
6	//
7	// Purpose:	A basic SKID buffer.
8	// {{{
9	//	Skid buffers are required for high throughput AXI code, since the AXI
10	//	specification requires that all outputs be registered.  This means
11	//	that, if there are any stall conditions calculated, it will take a clock
12	//	cycle before the stall can be propagated up stream.  This means that
13	//	the data will need to be buffered for a cycle until the stall signal
14	//	can make it to the output.
15	//
16	//	Handling that buffer is the purpose of this core.
17	//
18	//	On one end of this core, you have the i_valid and i_data inputs to
19	//	connect to your bus interface.  There's also a registered o_ready
20	//	signal to signal stalls for the bus interface.
21	//
22	//	The other end of the core has the same basic interface, but it isn't
23	//	registered.  This allows you to interact with the bus interfaces
24	//	as though they were combinatorial logic, by interacting with this half
25	//	of the core.
26	//
27	//	If at any time the incoming !stall signal, i_ready, signals a stall,
28	//	the incoming data is placed into a buffer.  Internally, that buffer
29	//	is held in r_data with the r_valid flag used to indicate that valid
30	//	data is within it.
31	// }}}
32	// Parameters:
33	// {{{
34	//	DW or data width
35	//		In order to make this core generic, the width of the data in the
36	//		skid buffer is parameterized
37	//
38	//	OPT_LOWPOWER
39	//		Forces both o_data and r_data to zero if the respective *VALID
40	//		signal is also low.  While this costs extra logic, it can also
41	//		be used to guarantee that any unused values aren't toggling and
42	//		therefore unnecessarily using power.
43	//
44	//		This excess toggling can be particularly problematic if the
45	//		bus signals have a high fanout rate, or a long signal path
46	//		across an FPGA.
47	//
48	//	OPT_OUTREG
49	//		Causes the outputs to be registered
50	//
51	//	OPT_PASSTHROUGH
52	//		Turns the skid buffer into a passthrough.  Used for formal
53	//		verification only.
54	// }}}
55	// Creator:	Dan Gisselquist, Ph.D.
56	//		Gisselquist Technology, LLC
57	//
58	////////////////////////////////////////////////////////////////////////////////
59	// }}}
60	// Copyright (C) 2019-2025, Gisselquist Technology, LLC
61	// {{{
62	// This program is free software (firmware): you can redistribute it and/or
63	// modify it under the terms of the GNU General Public License as published
64	// by the Free Software Foundation, either version 3 of the License, or (at
65	// your option) any later version.
66	//
67	// This program is distributed in the hope that it will be useful, but WITHOUT
68	// ANY WARRANTY; without even the implied warranty of MERCHANTIBILITY or
69	// FITNESS FOR A PARTICULAR PURPOSE.  See the GNU General Public License
70	// for more details.
71	//
72	// You should have received a copy of the GNU General Public License along
73	// with this program.  (It's in the $(ROOT)/doc directory.  Run make with no
74	// target there if the PDF file isn't present.)  If not, see
75	// <http://www.gnu.org/licenses/> for a copy.
76	// }}}
77	// License:	GPL, v3, as defined and found on www.gnu.org,
78	// {{{
79	//		http://www.gnu.org/licenses/gpl.html
80	//
81	////////////////////////////////////////////////////////////////////////////////
82	//
83	//
84	`default_nettype none
85	// }}}
86	module skidbuffer #(
87			// {{{
88			parameter	[0:0]	OPT_LOWPOWER = 0,
89			parameter	[0:0]	OPT_OUTREG = 1,
90			//
91			parameter	[0:0]	OPT_PASSTHROUGH = 0,
92			parameter		DW = 8,
93			parameter	[0:0]	OPT_INITIAL = 1'b1
94			// }}}
95		) (
96			// {{{
97			input	wire			i_clk, i_reset,
98			input	wire			i_valid,
99			output	wire			o_ready,
100			input	wire	[DW-1:0]	i_data,
101			output	wire			o_valid,
102			input	wire			i_ready,
103			output	reg	[DW-1:0]	o_data
104			// }}}
105		);
106	
107		wire	[DW-1:0]	w_data;
108	
109		generate if (OPT_PASSTHROUGH)
110		begin : PASSTHROUGH
111			// {{{
112			assign	{ o_valid, o_ready } = { i_valid, i_ready };
113	
114			always @(*)
115			if (!i_valid && OPT_LOWPOWER)
116				o_data = 0;
117			else
118				o_data = i_data;
119	
120			assign	w_data = 0;
121	
122			// Keep Verilator happy
123			// Verilator lint_off UNUSED
124			// {{{
125			wire	unused_passthrough;
126			assign	unused_passthrough = &{ 1'b0, i_clk, i_reset };
127			// }}}
128			// Verilator lint_on  UNUSED
129			// }}}
130		end else begin : LOGIC
131			// We'll start with skid buffer itself
132			// {{{
133			reg			r_valid;
134			reg	[DW-1:0]	r_data;
135	
136			// r_valid
137			// {{{
138			initial if (OPT_INITIAL) r_valid = 0;
139			always @(posedge i_clk)
140			if (i_reset)
141				r_valid <= 0;
142			else if ((i_valid && o_ready) && (o_valid && !i_ready))
143				// We have incoming data, but the output is stalled
144				r_valid <= 1;
145			else if (i_ready)
146				r_valid <= 0;
147			// }}}
148	
149			// r_data
150			// {{{
151			initial if (OPT_INITIAL) r_data = 0;
152			always @(posedge i_clk)
153			if (OPT_LOWPOWER && i_reset)
154				r_data <= 0;
155			else if (OPT_LOWPOWER && (!o_valid || i_ready))
156				r_data <= 0;
157			else if ((!OPT_LOWPOWER || !OPT_OUTREG || i_valid) && o_ready)
158				r_data <= i_data;
159	
160			assign	w_data = r_data;
161			// }}}
162	
163			// o_ready
164			// {{{
165			assign o_ready = !r_valid;
166			// }}}
167	
168			//
169			// And then move on to the output port
170			//
171			if (!OPT_OUTREG)
172			begin : NET_OUTPUT
173				// Outputs are combinatorially determined from inputs
174				// {{{
175				// o_valid
176				// {{{
177				assign	o_valid = !i_reset && (i_valid || r_valid);
178				// }}}
179	
180				// o_data
181				// {{{
182				always @(*)
183				if (r_valid)
184					o_data = r_data;
185				else if (!OPT_LOWPOWER || i_valid)
186					o_data = i_data;
187				else
188					o_data = 0;
189				// }}}
190				// }}}
191			end else begin : REG_OUTPUT
192				// Register our outputs
193				// {{{
194				// o_valid
195				// {{{
196				reg	ro_valid;
197	
198				initial if (OPT_INITIAL) ro_valid = 0;
199				always @(posedge i_clk)
200				if (i_reset)
201					ro_valid <= 0;
202				else if (!o_valid || i_ready)
203					ro_valid <= (i_valid || r_valid);
204	
205				assign	o_valid = ro_valid;
206				// }}}
207	
208				// o_data
209				// {{{
210				initial if (OPT_INITIAL) o_data = 0;
211				always @(posedge i_clk)
212				if (OPT_LOWPOWER && i_reset)
213					o_data <= 0;
214				else if (!o_valid || i_ready)
215				begin
216	
217					if (r_valid)
218						o_data <= r_data;
219					else if (!OPT_LOWPOWER || i_valid)
220						o_data <= i_data;
221					else
222						o_data <= 0;
223				end
224				// }}}
225	
226				// }}}
227			end
228			// }}}
229		end endgenerate
230	
231		// Keep Verilator happy
232		// {{{
233		// verilator coverage_off
234		// Verilator lint_off UNUSED
235		wire	unused;
236		assign	unused = &{ 1'b0, w_data };
237		// Verilator lint_on  UNUSED
238		// verilator coverage_on
239		// }}}
240	////////////////////////////////////////////////////////////////////////////////
241	////////////////////////////////////////////////////////////////////////////////
242	////////////////////////////////////////////////////////////////////////////////
243	//
244	// Formal properties
245	// {{{
246	////////////////////////////////////////////////////////////////////////////////
247	////////////////////////////////////////////////////////////////////////////////
248	////////////////////////////////////////////////////////////////////////////////
249	`ifdef	FORMAL
250	`ifdef	SKIDBUFFER
251	`define	ASSUME	assume
252	`else
253	`define	ASSUME	assert
254	`endif
255	
256		reg	f_past_valid;
257	
258		initial	f_past_valid = 0;
259		always @(posedge i_clk)
260			f_past_valid <= 1;
261	
262		always @(*)
263		if (!f_past_valid)
264			assume(i_reset);
265	
266		////////////////////////////////////////////////////////////////////////
267		//
268		// Incoming stream properties / assumptions
269		// {{{
270		////////////////////////////////////////////////////////////////////////
271		//
272		always @(posedge i_clk)
273		if (!f_past_valid)
274		begin
275			`ASSUME(!i_valid || !OPT_INITIAL);
276		end else if ($past(i_valid && !o_ready && !i_reset) && !i_reset)
277			`ASSUME(i_valid && $stable(i_data));
278	
279	`ifdef	VERIFIC
280	`define	FORMAL_VERIFIC
281		// Reset properties
282		property RESET_CLEARS_IVALID;
283			@(posedge i_clk) i_reset |=> !i_valid;
284		endproperty
285	
286		property IDATA_HELD_WHEN_NOT_READY;
287			@(posedge i_clk) disable iff (i_reset)
288			i_valid && !o_ready |=> i_valid && $stable(i_data);
289		endproperty
290	
291	`ifdef	SKIDBUFFER
292		assume	property (IDATA_HELD_WHEN_NOT_READY);
293	`else
294		assert	property (IDATA_HELD_WHEN_NOT_READY);
295	`endif
296	`endif
297		// }}}
298		////////////////////////////////////////////////////////////////////////
299		//
300		// Outgoing stream properties / assumptions
301		// {{{
302		////////////////////////////////////////////////////////////////////////
303		//
304	
305		generate if (!OPT_PASSTHROUGH)
306		begin
307	
308			always @(posedge i_clk)
309			if (!f_past_valid) // || $past(i_reset))
310			begin
311				// Following any reset, valid must be deasserted
312				assert(!o_valid || !OPT_INITIAL);
313			end else if ($past(o_valid && !i_ready && !i_reset) && !i_reset)
314				// Following any stall, valid must remain high and
315				// data must be preserved
316				assert(o_valid && $stable(o_data));
317	
318		end endgenerate
319		// }}}
320		////////////////////////////////////////////////////////////////////////
321		//
322		// Other properties
323		// {{{
324		////////////////////////////////////////////////////////////////////////
325		//
326		//
327		generate if (!OPT_PASSTHROUGH)
328		begin
329			// Rule #1:
330			//	If registered, then following any reset we should be
331			//	ready for a new request
332			// {{{
333			always @(posedge i_clk)
334			if (f_past_valid && $past(OPT_OUTREG && i_reset))
335				assert(o_ready);
336			// }}}
337	
338			// Rule #2:
339			//	All incoming data must either go directly to the
340			//	output port, or into the skid buffer
341			// {{{
342	`ifndef	VERIFIC
343			always @(posedge i_clk)
344			if (f_past_valid && !$past(i_reset) && $past(i_valid && o_ready
345				&& (!OPT_OUTREG || o_valid) && !i_ready))
346				assert(!o_ready && w_data == $past(i_data));
347	`else
348			assert property (@(posedge i_clk)
349				disable iff (i_reset)
350				(i_valid && o_ready
351					&& (!OPT_OUTREG || o_valid) && !i_ready)
352					|=> (!o_ready && w_data == $past(i_data)));
353	`endif
354			// }}}
355	
356			// Rule #3:
357			//	After the last transaction, o_valid should become idle
358			// {{{
359			if (!OPT_OUTREG)
360			begin
361				// {{{
362				always @(posedge i_clk)
363				if (f_past_valid && !$past(i_reset) && !i_reset
364						&& $past(i_ready))
365				begin
366					assert(o_valid == i_valid);
367					assert(!i_valid || (o_data == i_data));
368				end
369				// }}}
370			end else begin
371				// {{{
372				always @(posedge i_clk)
373				if (f_past_valid && !$past(i_reset))
374				begin
375					if ($past(i_valid && o_ready))
376						assert(o_valid);
377	
378					if ($past(!i_valid && o_ready && i_ready))
379						assert(!o_valid);
380				end
381				// }}}
382			end
383			// }}}
384	
385			// Rule #4
386			//	Same thing, but this time for o_ready
387			// {{{
388			always @(posedge i_clk)
389			if (f_past_valid && $past(!o_ready && i_ready))
390				assert(o_ready);
391			// }}}
392	
393			// If OPT_LOWPOWER is set, o_data and w_data both need to be
394			// zero any time !o_valid or !r_valid respectively
395			// {{{
396			if (OPT_LOWPOWER)
397			begin
398				always @(*)
399				if ((OPT_OUTREG || !i_reset) && !o_valid)
400					assert(o_data == 0);
401	
402				always @(*)
403				if (o_ready)
404					assert(w_data == 0);
405	
406			end
407			// }}}
408		end endgenerate
409		// }}}
410		////////////////////////////////////////////////////////////////////////
411		//
412		// Cover checks
413		// {{{
414		////////////////////////////////////////////////////////////////////////
415		//
416		//
417	`ifdef	SKIDBUFFER
418		generate if (!OPT_PASSTHROUGH)
419		begin
420			reg	f_changed_data;
421	
422			initial	f_changed_data = 0;
423			always @(posedge i_clk)
424			if (i_reset)
425				f_changed_data <= 1;
426			else if (i_valid && $past(!i_valid || o_ready))
427			begin
428				if (i_data != $past(i_data + 1))
429					f_changed_data <= 0;
430			end else if (!i_valid && i_data != 0)
431				f_changed_data <= 0;
432	
433	
434	`ifndef	VERIFIC
435			reg	[3:0]	cvr_steps, cvr_hold;
436	
437			always @(posedge i_clk)
438			if (i_reset)
439			begin
440				cvr_steps <= 0;
441				cvr_hold  <= 0;
442			end else begin
443				cvr_steps <= cvr_steps + 1;
444				cvr_hold  <= cvr_hold  + 1;
445				case(cvr_steps)
446				 0: if (o_valid || i_valid)
447					cvr_steps <= 0;
448				 1: if (!i_valid || !i_ready)
449					cvr_steps <= 0;
450				 2: if (!i_valid || !i_ready)
451					cvr_steps <= 0;
452				 3: if (!i_valid || !i_ready)
453					cvr_steps <= 0;
454				 4: if (!i_valid ||  i_ready)
455					cvr_steps <= 0;
456				 5: if (!i_valid || !i_ready)
457					cvr_steps <= 0;
458				 6: if (!i_valid || !i_ready)
459					cvr_steps <= 0;
460				 7: if (!i_valid ||  i_ready)
461					cvr_steps <= 0;
462				 8: if (!i_valid ||  i_ready)
463					cvr_steps <= 0;
464				 9: if (!i_valid || !i_ready)
465					cvr_steps <= 0;
466				10: if (!i_valid || !i_ready)
467					cvr_steps <= 0;
468				11: if (!i_valid || !i_ready)
469					cvr_steps <= 0;
470				12: begin
471					cvr_steps <= cvr_steps;
472					cover(!o_valid && !i_valid && f_changed_data);
473					if (!o_valid || !i_ready)
474						cvr_steps <= 0;
475					else
476						cvr_hold <= cvr_hold + 1;
477					end
478				default: assert(0);
479				endcase
480			end
481	
482	`else
483			// Cover test
484			cover property (@(posedge i_clk)
485				disable iff (i_reset)
486				(!o_valid && !i_valid)
487				##1 i_valid &&  i_ready [*3]
488				##1 i_valid && !i_ready
489				##1 i_valid &&  i_ready [*2]
490				##1 i_valid && !i_ready [*2]
491				##1 i_valid &&  i_ready [*3]
492				// Wait for the design to clear
493				##1 o_valid && i_ready [*0:5]
494				##1 (!o_valid && !i_valid && f_changed_data));
495	`endif
496		end endgenerate
497	`endif	// SKIDBUFFER
498		// }}}
499	`endif
500	// }}}
501	endmodule
502

