	// The way this works, though, the CPU will stall once the flash
	// cache gets access to the bus--the CPU will be stuck until the
	// flash cache is finished with the bus.
	wbpriarbiter #(
		// {{{
		.DW(BUS_WIDTH),
		.AW(PAW)
		// }}}
	) dmacvcpu(
