			dc_stall, dc_ack, dc_err,
		ext_cyc, ext_stb, ext_we, ext_addr, ext_odata, ext_sel,
			ext_stall, ext_ack, ext_err
		// }}}
	);
	assign	mmu_idata = ext_idata;
